scripts.build:
rm -rf dist && tsc -p tsconfig.server.json && tsc -p tsconfig.browser.json && tsc -p tsconfig.worker.json && mkdir -p dist/public && cp public/index.html public/styles.css public/manifest.webmanifest public/icon.svg dist/public/ && printf '{
  "type": "module"
}
' > dist/package.json
